package app.geometrypanel.mobile;

import java.io.IOException;
import java.nio.ByteBuffer;
import java.util.Base64;
import java.util.zip.CRC32;

/** Only a bounded, structurally complete PNG generated by the panel can reach the document picker. */
final class PanelImage {
    static final int MAX = 1048576;
    private PanelImage() { }
    static byte[] decode(String text) throws IOException {
        if (text == null || text.length() > 1398104 || !text.matches("[A-Za-z0-9+/]*={0,2}")) throw new IOException("invalid_panel_image");
        final byte[] raw; try { raw = Base64.getDecoder().decode(text); } catch (IllegalArgumentException error) { throw new IOException("invalid_panel_image"); }
        if (raw.length < 57 || raw.length > MAX || ByteBuffer.wrap(raw).getLong() != 0x89504e470d0a1a0aL) throw new IOException("invalid_panel_image");
        int cursor = 8; boolean header = false, data = false, end = false;
        while (cursor + 12 <= raw.length) {
            int length = ByteBuffer.wrap(raw, cursor, 4).getInt();
            if (length < 0 || length > raw.length - cursor - 12) throw new IOException("invalid_panel_image");
            int kind = ByteBuffer.wrap(raw, cursor + 4, 4).getInt(); CRC32 crc = new CRC32(); crc.update(raw, cursor + 4, length + 4);
            if (crc.getValue() != (ByteBuffer.wrap(raw, cursor + length + 8, 4).getInt() & 0xffffffffL)) throw new IOException("invalid_panel_image");
            if (!header) {
                if (kind != 0x49484452 || length != 13) throw new IOException("invalid_panel_image");
                int width = ByteBuffer.wrap(raw, cursor + 8, 4).getInt(), height = ByteBuffer.wrap(raw, cursor + 12, 4).getInt();
                if (width < 1 || height < 1 || width > 2048 || height > 2048) throw new IOException("invalid_panel_image"); header = true;
            } else if (kind == 0x49484452) throw new IOException("invalid_panel_image");
            if (kind == 0x49444154) data = true;
            cursor += length + 12;
            if (kind == 0x49454e44) { if (length != 0 || cursor != raw.length) throw new IOException("invalid_panel_image"); end = true; break; }
        }
        if (!header || !data || !end) throw new IOException("invalid_panel_image");
        return raw;
    }
}
